def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = [sum(v == c for row in grid for v in row) for c in range(10)]
    background = counts.index(max(counts))

    def runs(side):
        n = w if side in ('top', 'bottom') else h
        if side == 'top': values = grid[0]
        elif side == 'bottom': values = grid[-1]
        elif side == 'left': values = [grid[r][0] for r in range(h)]
        else: values = [grid[r][-1] for r in range(h)]
        result = []
        i = 0
        while i < n:
            if values[i] == background:
                i += 1
                continue
            color, j = values[i], i + 1
            while j < n and values[j] == color:
                j += 1
            result.append((color, i, j))
            i = j
        return result

    def cell(side, pos, offset):
        if side == 'left': return pos, offset
        if side == 'right': return pos, w - 1 - offset
        if side == 'top': return offset, pos
        return h - 1 - offset, pos

    for side_a, side_b in (('left', 'right'), ('top', 'bottom')):
        for color, a0, a1 in runs(side_a):
            for color_b, b0, b1 in runs(side_b):
                if color != color_b or a1-a0 != b1-b0:
                    continue
                # A mark aligned with the border segment sends its own color
                # toward that border, and a matching ray from the paired bar.
                for k in range(a1-a0):
                    positions = ((side_a, a0+k, b0+k), (side_b, b0+k, a0+k))
                    for source, pos, opposite_pos in positions:
                        offsets = range(1, w-1) if source in ('left', 'right') else range(1, h-1)
                        marks = []
                        for offset in offsets:
                            r, c = cell(source, pos, offset)
                            value = grid[r][c]
                            if value != background and value != color:
                                marks.append((r, c, value))
                        for r, c, mark_color in marks:
                            out[r][c] = 4
                            # Draw from the mark toward its own border. Do not
                            # overwrite the non-background border/object cells.
                            if source == 'left':
                                ray = [(r, x) for x in range(c-1, -1, -1)]
                            elif source == 'right':
                                ray = [(r, x) for x in range(c+1, w)]
                            elif source == 'top':
                                ray = [(y, c) for y in range(r-1, -1, -1)]
                            else:
                                ray = [(y, c) for y in range(r+1, h)]
                            for rr, cc in ray:
                                if grid[rr][cc] == background:
                                    out[rr][cc] = mark_color
                            # Project the mark's color from the corresponding
                            # cell on the opposite bar across to the far edge.
                            other_side = side_b if source == side_a else side_a
                            perpendicular = w if other_side in ('left', 'right') else h
                            opp_ray = [cell(other_side, opposite_pos, offset)
                                       for offset in range(1, perpendicular)]
                            for rr, cc in opp_ray:
                                if grid[rr][cc] == background:
                                    out[rr][cc] = mark_color
    return out

